import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Filler,
} from 'chart.js';
import { useAuth } from '../context/AuthContext';
import { getHistory } from '../services/api';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Filler);

const riskBadge = (p) => {
  if (!p) return '—';
  const cls = p.includes('High') ? 'risk-high' : p.includes('Moderate') ? 'risk-moderate' : 'risk-low';
  const icon = p.includes('High') ? 'bi-exclamation-triangle' : p.includes('Moderate') ? 'bi-dash-circle' : 'bi-check-circle';
  return <span className={`risk-badge ${cls}`}><i className={`bi ${icon}`} /> {p}</span>;
};

export default function Dashboard() {
  const { user } = useAuth();
  const [history, setHistory] = useState([]);

  useEffect(() => {
    getHistory().then((r) => setHistory(r.data.history || [])).catch(() => {});
  }, []);

  const latest = history[0];
  const chartData = {
    labels: history.slice(0, 10).reverse().map((h) => new Date(h.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })),
    datasets: [{
      label: 'Confidence %',
      data: history.slice(0, 10).reverse().map((h) => h.confidence),
      borderColor: '#6366f1',
      backgroundColor: 'rgba(99, 102, 241, 0.1)',
      fill: true,
      tension: 0.4,
      pointRadius: 4,
      pointBackgroundColor: '#6366f1',
    }],
  };

  const chartOptions = {
    responsive: true,
    plugins: { legend: { display: false } },
    scales: {
      y: { min: 0, max: 100, grid: { color: 'rgba(148,163,184,0.15)' } },
      x: { grid: { display: false } },
    },
  };

  return (
    <div className="fade-in">
      <div className="welcome-banner mb-4">
        <div className="row align-items-center">
          <div className="col-md-8">
            <h1 className="mb-2" style={{ WebkitTextFillColor: 'unset', color: 'var(--mw-text)' }}>
              Hello, {user?.name?.split(' ')[0]} 👋
            </h1>
            <p className="text-muted mb-3 mb-md-0">
              Your AI-powered mental health dashboard. Track depression risk, behavioral patterns, and wellness insights.
            </p>
          </div>
          <div className="col-md-4 text-md-end">
            <Link to="/assessment" className="btn btn-mw-primary me-2"><i className="bi bi-clipboard2-pulse me-1" />New Assessment</Link>
            <Link to="/chat" className="btn btn-outline-primary rounded-pill"><i className="bi bi-robot me-1" />Ask AI</Link>
          </div>
        </div>
      </div>

      <div className="row g-3 mb-4">
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon purple"><i className="bi bi-shield-heart" /></div>
            <div className="stat-label">Risk Status</div>
            <div className="mt-2">{riskBadge(latest?.prediction) || <span className="text-muted">No data</span>}</div>
          </div>
        </div>
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon cyan"><i className="bi bi-speedometer2" /></div>
            <div className="stat-label">AI Confidence</div>
            <div className="stat-value">{latest?.confidence != null ? `${latest.confidence}%` : '—'}</div>
          </div>
        </div>
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon green"><i className="bi bi-journal-check" /></div>
            <div className="stat-label">Assessments</div>
            <div className="stat-value">{history.length}</div>
          </div>
        </div>
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon amber"><i className="bi bi-moon-stars" /></div>
            <div className="stat-label">Sleep Score</div>
            <div className="stat-value">{latest?.sleep_score ?? '—'}<small className="text-muted fs-6">/10</small></div>
          </div>
        </div>
      </div>

      <div className="row g-4">
        <div className="col-lg-8">
          <div className="card-mw p-4">
            <div className="d-flex justify-content-between align-items-center mb-3">
              <h5 className="mb-0"><i className="bi bi-graph-up text-primary me-2" />Confidence Trend</h5>
              <Link to="/analytics" className="btn btn-sm btn-outline-primary">View Analytics</Link>
            </div>
            {history.length > 0 ? <Line data={chartData} options={chartOptions} /> : (
              <div className="text-center py-5 text-muted">
                <i className="bi bi-bar-chart display-4 d-block mb-2 opacity-25" />
                Complete an assessment to unlock AI insights
              </div>
            )}
          </div>
        </div>
        <div className="col-lg-4">
          <div className="card-mw p-4 h-100">
            <h5 className="mb-3"><i className="bi bi-activity text-primary me-2" />Latest Vitals</h5>
            {latest ? (
              <ul className="list-unstyled mb-0">
                {[
                  ['Sleep', latest.sleep_score, '/10', 'bi-moon'],
                  ['Stress', latest.stress_score, '/10', 'bi-lightning'],
                  ['Walking', latest.walking_pct, '%', 'bi-person-walking'],
                  ['Running', latest.running_pct, '%', 'bi-heart-pulse'],
                  ['Activity', latest.activity_level, '/10', 'bi-bicycle'],
                ].map(([l, v, u, ic]) => (
                  <li key={l} className="d-flex justify-content-between align-items-center py-2 border-bottom border-opacity-10">
                    <span><i className={`bi ${ic} me-2 text-primary`} />{l}</span>
                    <strong>{v}{u}</strong>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-muted">No assessment data yet.</p>
            )}
            <Link to="/recommendations" className="btn btn-sm btn-mw-primary w-100 mt-3">Get Recommendations</Link>
          </div>
        </div>
      </div>
    </div>
  );
}
